import Foundation

extension MockedSubscriptType {

    /// A parsing error generated by ``MockedSubscriptType``.
    enum ParsingError: CaseIterable, CustomStringConvertible, Error {

        // MARK: Cases

        /// An error indicating that ``MockedSubscriptType`` was unable to parse
        /// a valid instance from the provided macro argument.
        case unableToParseSubscriptType

        // MARK: Properties

        /// The description of the error.
        var description: String {
            switch self {
            case .unableToParseSubscriptType:
                "Unable to parse subscript type."
            }
        }
    }
}
